INSERT INTO public.clinics (id, name, address, area, phone, email, about, specialty_ids, services, facilities, languages, fee_range, rating, review_count) VALUES
('11111111-1111-1111-1111-111111111111', 'Little Steps Clinic', '12, 3rd Main Road, Gandhi Nagar, Adyar, Chennai 600020', 'Adyar', '+91 44 4000 1201', 'hello@littlesteps.demo', 'A neighbourhood child and family clinic offering paediatric care, vaccinations and routine health checks.', ARRAY['pediatrics','general','dermatology']::TEXT[], ARRAY['Vaccination','Child growth monitoring','Fever clinic','Nutrition guidance']::TEXT[], ARRAY['Wheelchair access','Pharmacy','Waiting lounge','Card payments']::TEXT[], ARRAY['English','Tamil','Hindi']::TEXT[], ARRAY[400,700]::NUMERIC[], 4.8, 126),
('22222222-2222-2222-2222-222222222222', 'Anna Nagar Ortho & Physio Centre', '45, 2nd Avenue, Anna Nagar West, Chennai 600040', 'Anna Nagar', '+91 44 4000 2204', 'care@annanagarortho.demo', 'Orthopaedic consultations, sports injury reviews and physiotherapy under one roof.', ARRAY['orthopedics','general','neurology']::TEXT[], ARRAY['Fracture care','Physiotherapy','Sports injury review','Digital X-ray']::TEXT[], ARRAY['On-site X-ray','Lift access','Parking','Insurance desk']::TEXT[], ARRAY['English','Tamil','Telugu']::TEXT[], ARRAY[600,900]::NUMERIC[], 4.6, 214),
('33333333-3333-3333-3333-333333333333', 'Velachery Family Health Point', '8, Vijayanagar Main Road, Velachery, Chennai 600042', 'Velachery', '+91 44 4000 3310', 'front.desk@vfhp.demo', 'Everyday family medicine, diabetes follow-ups and preventive health check packages.', ARRAY['general','cardiology','ent']::TEXT[], ARRAY['Health check packages','Diabetes follow-up','ECG','Blood collection']::TEXT[], ARRAY['Lab collection','Parking','Card payments']::TEXT[], ARRAY['English','Tamil']::TEXT[], ARRAY[350,800]::NUMERIC[], 4.5, 98),
('44444444-4444-4444-4444-444444444444', 'T. Nagar Skin & Smile Studio', '22, Thanikachalam Road, T. Nagar, Chennai 600017', 'T. Nagar', '+91 44 4000 4488', 'appointments@skinsmile.demo', 'Dermatology and dental care clinic with evening consultation hours.', ARRAY['dermatology','dentistry']::TEXT[], ARRAY['Acne care','Dental cleaning','Root canal','Skin allergy review']::TEXT[], ARRAY['Evening hours','Card payments','Air-conditioned waiting']::TEXT[], ARRAY['English','Tamil','Malayalam']::TEXT[], ARRAY[500,1000]::NUMERIC[], 4.7, 173),
('55555555-5555-5555-5555-555555555555', 'Nungambakkam Women''s Care', '5, Sterling Road, Nungambakkam, Chennai 600034', 'Nungambakkam', '+91 44 4000 5519', 'reception@nwcare.demo', 'Gynaecology, antenatal follow-ups and women''s preventive health consultations.', ARRAY['gynecology','general','ophthalmology']::TEXT[], ARRAY['Antenatal care','Ultrasound','PCOS consultation','Well-woman check']::TEXT[], ARRAY['Female staff on duty','Lift access','Pharmacy']::TEXT[], ARRAY['English','Tamil','Hindi']::TEXT[], ARRAY[600,1100]::NUMERIC[], 4.9, 241),
('66666666-6666-6666-6666-666666666666', 'OMR Neuro & Eye Clinic', 'Unit 3, Thoraipakkam, Old Mahabalipuram Road, Chennai 600097', 'OMR', '+91 44 4000 6627', 'desk@omrneuroeye.demo', 'Neurology and ophthalmology consultations for the IT corridor.', ARRAY['neurology','ophthalmology','ent']::TEXT[], ARRAY['Headache clinic','Eye check','Spectacle prescription','Sleep review']::TEXT[], ARRAY['Late evening slots','Parking','Wheelchair access']::TEXT[], ARRAY['English','Tamil','Hindi']::TEXT[], ARRAY[700,1200]::NUMERIC[], 4.4, 87)
